      slides[current].scrollIntoView({ behavior: 'smooth' });
    }
    document.addEventListener('keydown', (event) => {
      if (['ArrowRight', 'PageDown', ' '].includes(event.key)) go(current + 1);
      if (['ArrowLeft', 'PageUp'].includes(event.key)) go(current - 1);
